mapper.select:
SELECT 
FROM location scoped
JOIN location_timeline timeline
  ON timeline.location_id = scoped.location_id
JOIN location_revision revision
  ON revision.location_revision_id = timeline.location_revision_id
WHERE scoped.location_id = #{locationId}
  AND timeline.business_effective_from <= #{asOf}
  AND timeline.recorded_at <= #{knowledgeAsOf}
  AND NOT EXISTS (
      SELECT 1
      FROM location_timeline newer
      WHERE newer.location_id = timeline.location_id
        AND newer.business_effective_from <= #{asOf}
        AND newer.recorded_at <= #{knowledgeAsOf}
        AND newer.event_sequence > timeline.event_sequence
  )
ORDER BY timeline.event_sequence, revision.location_revision_id

SELECT COUNT(*)
FROM location_revision revision
WHERE revision.location_id = #{locationId}

