SELECT FROM attendance_group_assignment assignment JOIN attendance_group_revision group_revision ON group_revision.attendance_group_revision_id = assignment.attendance_group_revision_id JOIN attendance_group scoped ON scoped.attendance_group_id = group_revision.attendance_group_id JOIN employee assigned_employee ON assigned_employee.employee_id = assignment.employee_id AND assigned_employee.company_id = scoped.company_id JOIN attendance_assignment_timeline latest_timeline ON latest_timeline.attendance_group_assignment_id = assignment.attendance_group_assignment_id AND latest_timeline.event_sequence = ( SELECT MAX(latest.event_sequence) FROM attendance_assignment_timeline latest WHERE latest.attendance_group_assignment_id = assignment.attendance_group_assignment_id ) WHERE scoped.attendance_group_id = #{groupId}
AND assignment.effective_from <= #{asOf} AND NOT EXISTS ( SELECT 1 FROM attendance_assignment_timeline inactive WHERE inactive.attendance_group_assignment_id = assignment.attendance_group_assignment_id AND inactive.state = 'INACTIVE' AND inactive.business_effective_from <= #{asOf} ) AND NOT EXISTS ( SELECT 1 FROM attendance_group_assignment successor WHERE successor.supersedes_assignment_id = assignment.attendance_group_assignment_id AND successor.effective_from <= #{asOf} )
ORDER BY assignment.effective_from, assignment.employee_id, assignment.attendance_group_assignment_id LIMIT #{limit} OFFSET #{offset}

SELECT CASE WHEN EXISTS (
    SELECT 1
    FROM attendance_group_assignment assignment
    JOIN attendance_group_revision group_revision
      ON group_revision.attendance_group_revision_id =
            assignment.attendance_group_revision_id
    JOIN attendance_group scoped
      ON scoped.attendance_group_id =
            group_revision.attendance_group_id
    JOIN employee assigned_employee
      ON assigned_employee.employee_id = assignment.employee_id
    JOIN attendance_assignment_timeline latest_timeline
      ON latest_timeline.attendance_group_assignment_id =
            assignment.attendance_group_assignment_id
    WHERE assignment.employee_id = #{employeeId}
      AND assigned_employee.company_id <> scoped.company_id
      AND assignment.effective_from <= #{asOf}
      AND assignment.created_at <= #{knowledgeAsOf}
      AND latest_timeline.business_effective_from <= #{asOf}
      AND latest_timeline.recorded_at <= #{knowledgeAsOf}
      AND latest_timeline.state = 'ACTIVE'
      AND NOT EXISTS (
          SELECT 1
          FROM attendance_assignment_timeline newer_timeline
          WHERE newer_timeline.attendance_group_assignment_id =
                    assignment.attendance_group_assignment_id
            AND newer_timeline.business_effective_from <= #{asOf}
            AND newer_timeline.recorded_at <= #{knowledgeAsOf}
            AND newer_timeline.event_sequence
                > latest_timeline.event_sequence
      )
      AND NOT EXISTS (
          SELECT 1
          FROM attendance_group_assignment successor
          WHERE successor.supersedes_assignment_id =
                    assignment.attendance_group_assignment_id
            AND successor.effective_from <= #{asOf}
            AND successor.created_at <= #{knowledgeAsOf}
      )
) THEN TRUE ELSE FALSE END

SELECT COALESCE(MAX(event_sequence), 0) + 1
FROM attendance_assignment_timeline
WHERE attendance_group_assignment_id = #{assignmentId}
